arguments.command:
cat > /app/s/post.py <<'EOF'
import numpy as np, json, sys
d=np.load("/app/s/lay.npz");M=d["M"];R=d["R"]
names=["any","no_touch","parallel","border","center_clear","clustered"]
obs=json.load(open("/app/s/obs.json"))
W=R/R.sum(0)  # layout x rule joint weight (x1/6)
logl=np.zeros(len(M))
rows=M.reshape(-1,6,6).sum(2); cols=M.reshape(-1,6,6).sum(1)
def scanlik(true,rep):
    p=np.zeros_like(true)
    for dd,pr in((-1,.15),(0,.7),(1,.15)):
        p+=pr*(np.clip(true+dd,0,6)==rep)
    return p
for o in obs:
    if o[0]=="fire":
        _,r,c,h=o; x=M[:,r*6+c]
        logl+=np.log(np.where(x==h,.9,.1))
    else:
        _,ax,i,v=o; t=rows[:,i] if ax=="row" else cols[:,i]
        logl+=np.log(scanlik(t,v))
lw=np.exp(logl-logl.max())
J=W*lw[:,None]; J/=J.sum()
pr=J.sum(0); pl=J.sum(1); occ=pl@M
def H(p): p=np.clip(p,1e-12,1); return -(p*np.log(p)).sum()
def Hc(o): o=np.clip(o,1e-12,1-1e-12); return -(o*np.log(o)+(1-o)*np.log(1-o)).sum()
def score_ent(Jw):
    s=Jw.sum(); 
    if s<=0: return 0
    J2=Jw/s; return H(J2.sum(0))/np.log(6)+Hc(J2.sum(1)@M)/20.1236
base=score_ent(J)
res=[]
for r in range(6):
  for c in range(6):
    x=M[:,r*6+c]; e=0
    for h in(0,1):
        l=np.where(x==h,.9,.1); Jw=J*l[:,None]; e+=Jw.sum()*score_ent(Jw)
    res.append(((base-e)/1,"fire",r,c))
for ax,T in(("row",rows),("col",cols)):
  for i in range(6):
    e=0
    for v in range(7):
        l=scanlik(T[:,i],v); Jw=J*l[:,None]; e+=Jw.sum()*score_ent(Jw)
    res.append(((base-e)/2,"scan",ax,i))
res.sort(reverse=True)
print("rules",dict(zip(names,np.round(pr,3))))
print(np.round(occ.reshape(6,6),2))
print("ent",base)
for x in res[:6]: print(x)
json.dump({"rules":dict(zip(names,pr.tolist())),"occ":occ.reshape(6,6).tolist()},open("/app/s/out.json","w"))
EOF
